  [1253456] = { "周囲にスライムを吐き出し、ターゲットに精神を抑制する粘液を浴びせます。\n\n効果が切れると、影響を受けたターゲットがSlime Novaを放ち、近くの味方に$N1のNatureダメージを与えます。", nil, 0x0a516fd9, nil, "um" },
  [1253463] = { "周囲にスライムを吐き出し、ターゲットに精神を抑制する粘液を浴びせます。\n\n効果が切れると、影響を受けたターゲットがSlime Novaを放ち、近くの味方に$N1のNatureダメージを与えます。", "良心が抑え込まれています。", 0xb8856333, 0xa02d0033, "uu" },
