  [1253480] = { "生きているSlimecontrolledのクリーチャーと冒険者をむさぼり、食べた犠牲者ごとに最大体力の$N1%のダメージを吸収するシールドを得ます。効果時間は$D1です。", "最大$N1のダメージを吸収しています。", 0x2441bab6, 0x37b5767b, "uu" },
  [1253487] = { "実験中の疫病をターゲットのモンスターに浴びせ、ほとんどの体力回復手段を永続的に封じます。\n\nThe Horror、Revildesh、Metamorphic Furyにのみ使用できます。", "体力回復の手段のほとんどが永久に抑え込まれています。", 0x7cb8ca2e, 0x836f5a85, "uu" },
