  [1253568] = { "$D2の間、$D1ごとに近くのすべてのグループメンバーの体力を$N1回復します。呪文を維持するには、ドルイドが詠唱を続ける必要があります。", "$D1ごとに近くのパーティメンバーを$N1回復します。", 0x1216d9a1, 0x793ba8c5, "uu" },
  [1253636] = { "The HorrorがCongealまたはCoagulateを詠唱すると、対象となったプレイヤーの最大体力の$N1%に等しいダメージを与えます。\n\nプレイヤー以外のターゲットは即死します。", nil, 0x6a717d14, nil, "um" },
