  [1253790] = { { "獲物のターゲットをむさぼり、ターゲットの最大体力の$N1%のダメージを与えて$D1の間スタンさせます。\n\nターゲットをむさぼることに成功するたびに、最大体力の$N3%回復します。", "獲物のターゲットをむさぼり、即座に倒します。\n\nターゲットをむさぼることに成功するたびに、最大体力の$N1%回復します。", shape = { "3/1", "1/0" } }, "食べられてしまいました！", 0xb8862dd1, 0xf5a4f322, "uu" },
