  [1253833] = { "devilsaurの分厚い皮が、受けるすべてのダメージを$N1%軽減します。\n\n棘の穴はこれを貫通でき、傷が癒えるまで一時的にこの効果を取り除きます。", "受けるすべてのダメージが$N1%減少します。\n\nトゲの落とし穴は、短い間この守りを貫通できます。", 0x0af01e6f, 0x871409ea, "uu" },
  [1253843] = { "最近棘の上を歩いたせいで痛い傷を負い、$D1ごとにスタックごとに$N1のPhysicalダメージを受けます。ダメージを受けるたびにスタックが1つ減ります。\n\nこの効果を受けている間は、Devilsaur Hideの恩恵を受けられません。", "出血により、$D1ごとに$N1のダメージを受けています。Devilsaur Hideの恩恵を受けられません。", 0x392f29cf, 0xd919a3b6, "uu" },
